import{_ as n,a0 as o,w as l,s as p,ao as u,I as r,x as t,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"關於哈希（散列）函數你應該知道的東西 | LCTT x X-CMD","titleTemplate":false,"description":"關於哈希（散列）函數你應該知道的東西 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於哈希（散列）函數你應該知道的東西 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於哈希（散列）函數你應該知道的東西 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200707 What you need to know about hash functions","title":"關於哈希（散列）函數你應該知道的東西","tag":"202007","desc":""},"relativePath":"202007/20200707 What you need to know about hash functions.md","filePath":"[post].md"}'),d={name:"202007/20200707 What you need to know about hash functions.md"};function b(h,e,f,m,y,g){const a=o("Link");return l(),p("div",null,[e[15]||(e[15]=u(`<h1 id="關於哈希-散列-函數你應該知道的東西" tabindex="-1">關於哈希（散列）函數你應該知道的東西 <a class="header-anchor" href="#關於哈希-散列-函數你應該知道的東西" aria-label="Permalink to “關於哈希（散列）函數你應該知道的東西”">​</a></h1><blockquote><p>從輸出的哈希值反推回輸入，這從計算的角度是不可行的。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/12/145709d3ne3vee330oh3lv.jpg" alt=""></p><p>無論安全從業人員用計算機做什麼，有一種工具對他們每個人都很有用：加密<ruby>哈希（散列）<rt>hash</rt></ruby>函數。這聽起來很神秘、很專業，甚至可能有點乏味，但是， 在這裏，關於什麼是哈希函數以及它們為什麼對你很重要，我會作出一個簡潔的解釋。</p><p>加密哈希函數，比如 SHA-256 或者 MD5，接受一組二進制數據（通常是字節）作為輸入，並且對每個可能的輸入集給出一個<ruby>希望唯一<rt>hopefully unique</rt></ruby>的輸出。對於任意模式的輸入，給定的哈希函數的輸出（“哈希值”）的長度都是一樣的（對於 SHA-256，是 32 字節或者 256 比特，這從名字中就能看出來）。最重要的是：從輸出的哈希值反推回輸入，這從計算的角度是<ruby>不可行的<rt>implausible</rt></ruby>（密碼學家討厭 “<ruby>不可能<rt>impossible</rt></ruby>” 這個詞）。這就是為什麼它們有時候被稱作<ruby>單向哈希函數<rt>one-way hash function</rt></ruby>。</p><p>但是哈希函數是用來做什麼的呢？為什麼“唯一”的屬性如此重要？</p><h3 id="唯一的輸出" tabindex="-1">唯一的輸出 <a class="header-anchor" href="#唯一的輸出" aria-label="Permalink to “唯一的輸出”">​</a></h3><p>在描述哈希函數的輸出時，“<ruby>希望唯一<rt>hopefully unique</rt></ruby>”這個短語是至關重要的，因為哈希函數就是用來呈現完全唯一的輸出。比如，哈希函數可以用於驗證 <em>你</em> 下載的文件副本的每一個字節是否和 <em>我</em> 下載的文件一樣。你下載一個 Linux 的 ISO 文件或者從 Linux 的倉庫中下載軟件時，你會看到使用這個驗證過程。沒有了唯一性，這個技術就沒用了，至少就通常的目的而言是這樣的。</p><p>如果兩個不同的輸入產生了相同的輸出，那麼這樣的哈希過程就稱作“<ruby>碰撞<rt>collision</rt></ruby>”。事實上，MD5 算法已經被棄用，因為雖然可能性微乎其微，但它現在可以用市面上的硬件和軟件系統找到碰撞。</p><p>另外一個重要的特性是，消息中的一個微小變化，甚至只是改變一個比特位，都可能會在輸出中產生一個明顯的變化（這就是“<ruby>雪崩效應<rt>avalanche effect</rt></ruby>”）。</p><h3 id="驗證二進制數據" tabindex="-1">驗證二進制數據 <a class="header-anchor" href="#驗證二進制數據" aria-label="Permalink to “驗證二進制數據”">​</a></h3><p>哈希函數的典型用途是當有人給你一段二進制數據，確保這些數據是你所期望的。無論是文本、可執行文件、視頻、圖像或者一個完整的資料庫數據，在計算世界中，所有的數據都可以用二進制的形式進行描述，所以至少可以這麼説，哈希是廣泛適用的。直接比較二進制數據是非常緩慢的且計算量巨大，但是哈希函數在設計上非常快。給定兩個大小為幾 M 或者幾 G 的文件，你可以事先生成它們的哈希值，然後在需要的時候再進行比較。</p><p>通常，對哈希值進行簽名比對大型數據集本身進行簽名更容易。這個特性太重要了，以至於密碼學中對哈希值最常見的應用就是生成“數字”簽名。</p><p>由於生成數據的哈希值很容易，所以通常不需要有兩套數據。假設你想在你的電腦上運行一個可執行文件。但是在你運行之前，你需要檢查這個文件就是你要的文件，沒有被黑客篡改。你可以方便快捷的對文件生成哈希值，只要你有一個這個哈希值的副本，你就可以相當肯定這就是你想要的文件。</p><p>下面是一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shasum -a256 ~/bin/fop</span></span>
<span class="line"><span>87227baf4e1e78f6499e4905e8640c1f36720ae5f2bd167de325fd0d4ebc791c  /home/bob/bin/fop</span></span></code></pre></div><p>如果我知道 <code>fop</code> 這個可執行文件的 SHA-256 校驗和，這是由供應商（這個例子中是 Apache 基金會）提供的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>87227baf4e1e78f6499e4905e8640c1f36720ae5f2bd167de325fd0d4ebc791c</span></span></code></pre></div><p>然後我就可以確信，我驅動器上的這個可執行文件和 Apache 基金會網站上發佈的文件是一模一樣的。這就是哈希函數難以發生碰撞（或者至少是 <em>很難通過計算得到碰撞</em>）這個性質的重要之處。如果黑客能將真實文件用哈希值相同的文件輕易的進行替換，那麼這個驗證過程就毫無用處。</p><p>事實上，這些性質還有更技術性的名稱，我上面所描述的將三個重要的屬性混在了一起。更準確地説，這些技術名稱是：</p><ol><li><ruby>抗原像性<rt>pre-image resistance</rt></ruby>：給定一個哈希值，即使知道用了什麼哈希函數，也很難得到用於創建它的消息。</li><li><ruby>抗次原像性<rt>second pre-image resistance</rt></ruby>：給定一個消息，很難找到另一個消息，使得這個消息可以產生相同的哈希值。</li><li><ruby>抗碰撞性<rt>collision resistance</rt></ruby>：很難得到任意兩個可以產生相同哈希值的消息。</li></ol><p><em>抗碰撞性</em> 和 <em>抗次原像性</em> 也許聽上去是同樣的性質，但它們具有細微而顯著的不同。<em>抗次原像性</em> 説的是如果 <em>已經</em> 有了一個消息，你也很難得到另一個與之哈希值相匹配的消息。<em>抗碰撞性</em> 使你很難找到兩個可以生成相同哈希值的消息，並且要在哈希函數中實現這一性質則更加困難。</p><p>讓我回到黑客試圖替換文件（可以通過哈希值進行校驗）的場景。現在，要在“外面”使用加密哈希算法（除了使用那些在現實世界中由獨角獸公司開發的完全無 Bug 且安全的實現之外），還有一些重要且困難的附加條件需要滿足。認真的讀者可能已經想到了其中一些，特別需要指出的是：</p><ol><li>你必須確保自己所擁有的哈希值副本也沒有被篡改。</li><li>你必須確保執行哈希算法的實體能夠正確執行並報告了結果。</li><li>你必須確保對比兩個哈希值的實體確實報告了這個對比的正確結果。</li></ol><p>確保你能滿足這些條件絕對不是一件容易的事。這就是<ruby>可信平台模組<rt>Trusted Platform Modules</rt></ruby>（TPM）成為許多計算系統一部分的原因之一。它們扮演着信任的硬件基礎，可以為驗證重要二進制數據真實性的加密工具提供保證。TPM 對於現實中的系統來説是有用且重要的工具，我也打算將來寫一篇關於 TPM 的文章。</p><hr>`,26)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://opensource.com/article/20/7/hash-functions"},{default:i(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/20/7/hash-functions",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("作者：",-1)),s(a,{href:"https://opensource.com/users/mikecamel"},{default:i(()=>[...e[2]||(e[2]=[t("Mike Bursell",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(a,{href:"https://github.com/Yufei-Yan"},{default:i(()=>[...e[4]||(e[4]=[t("Yufei-Yan",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const x=n(d,[["render",b]]);export{T as __pageData,x as default};
